// DOCUMENTS: Stage 6 component — a DNS resolver with a tick-TTL cache
// ledger... mirrors cache.js.
// CHECKS: constructor rejects non-mini-IP address and non-positive-integer ttlTicks.
export function createDns({ address = '10.60', ttlTicks = 300 } = {}) {
  if (!/^\d+\.\d+$/.test(address)) throw new Error(`dns: invalid mini-IP address ${address}`);
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  const authoritative = new Map([['example.com', '10.1']]);
  const ledger = new Map(); // name -> { name, target, cachedAtTick, expiresAtTick }
  let lookups = 0;
  let cachedHits = 0;
  let evictions = 0;
  let lastLookup = null;

  function evictExpired(currentTick = 0) {
    for (const entry of ledger.values()) {
      if (currentTick >= entry.expiresAtTick) { ledger.delete(entry.name); evictions += 1; }
    }
  }

  function lookup(name, currentTick = 0) {
    lookups += 1;
    evictExpired(currentTick);
    const entry = ledger.get(name);
    if (entry) {
      cachedHits += 1;
      lastLookup = { name, status: 'OK', source: 'cache', target: entry.target, atTick: currentTick };
      return { status: 'OK', target: entry.target, source: 'cache' };
    }
    const target = authoritative.get(name) ?? null;
    if (target !== null) {
      ledger.set(name, { name, target, cachedAtTick: currentTick, expiresAtTick: currentTick + ttlTicks });
      lastLookup = { name, status: 'OK', source: 'authoritative', target, atTick: currentTick };
      return { status: 'OK', target, source: 'authoritative' };
    }
    lastLookup = { name, status: 'NX', source: 'authoritative', target: null, atTick: currentTick };
    return { status: 'NX' };
  }

  function snapshot(currentTick = 0) {
    evictExpired(currentTick);
    return {
      address, ttlTicks, lookups, cachedHits, evictions, lastLookup,
      authoritative: [...authoritative.entries()].map(([name, target]) => ({ name, target })),
      cache: [...ledger.values()].map((e) => ({ name: e.name, target: e.target, cachedAtTick: e.cachedAtTick, expiresAtTick: e.expiresAtTick, ttlRemaining: e.expiresAtTick - currentTick })),
    };
  }

  return { get address() { return address; }, evictExpired, lookup, snapshot };
}
