// DOCUMENTS: the Stage 6 component — a DNS resolver with a tick-TTL cache
// ledger. The authoritative table (example.com -> 10.1; Stage 6b adds a CDN
// name) is consulted only on a cold lookup: every resolved name is written
// into the ledger with an expiry tick, and a lookup inside that TTL is
// answered from the ledger (cachedHits) with no authoritative consult. An
// entry past its expiry is gone before the lookup runs, so a stale record is
// re-consulted, not answered. Unknown names answer { status: 'NX' } — the
// browser renders the NX card and no GET is emitted; the throw rule belongs
// to cross-subnet addresses (network.js), not to the resolver.
//
// Deterministic by construction: no clock, no RNG — time arrives as the
// `currentTick` argument, the same way the Cache and WebServer keep time.
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP and a ttlTicks that is not a positive integer (fail-loud over
// silent mis-configuration).
export function createDns({ address = '10.60', ttlTicks = 300 } = {}) {
  if (!/^\d+\.\d+$/.test(address)) {
    throw new Error(`dns: invalid mini-IP address ${address}`);
  }
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) {
    throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  }
  const authoritative = new Map([['example.com', '10.1']]);
  const ledger = new Map(); // name -> { name, target, cachedAtTick, expiresAtTick }
  let lookups = 0;
  let cachedHits = 0;
  let evictions = 0;
  let lastLookup = null;

  // An entry is stale the moment the current tick reaches its expiry:
  // resolved at tick T with ttlTicks = 300 means alive through tick T + 299.
  function evictExpired(currentTick = 0) {
    for (const entry of ledger.values()) {
      if (currentTick >= entry.expiresAtTick) {
        ledger.delete(entry.name);
        evictions += 1;
      }
    }
  }

  // CHECKS: the cache branch answers only a live ledger entry (source
  // 'cache'); a miss or an expired entry consults the authoritative table
  // (source 'authoritative') and refills the ledger. lastLookup records
  // which branch ran, so tests and the inspector can pin that a hit inside
  // ttlTicks increments cachedHits with no authoritative consult.
  function lookup(name, currentTick = 0) {
    lookups += 1;
    evictExpired(currentTick);
    const entry = ledger.get(name);
    if (entry) {
      cachedHits += 1;
      lastLookup = {
        name,
        status: 'OK',
        source: 'cache',
        target: entry.target,
        atTick: currentTick,
      };
      return { status: 'OK', target: entry.target, source: 'cache' };
    }
    const target = authoritative.get(name) ?? null;
    if (target !== null) {
      ledger.set(name, {
        name,
        target,
        cachedAtTick: currentTick,
        expiresAtTick: currentTick + ttlTicks,
      });
      lastLookup = { name, status: 'OK', source: 'authoritative', target, atTick: currentTick };
      return { status: 'OK', target, source: 'authoritative' };
    }
    lastLookup = { name, status: 'NX', source: 'authoritative', target: null, atTick: currentTick };
    return { status: 'NX' };
  }

  function snapshot(currentTick = 0) {
    evictExpired(currentTick);
    return {
      address,
      ttlTicks,
      lookups,
      cachedHits,
      evictions,
      lastLookup,
      authoritative: [...authoritative.entries()].map(([name, target]) => ({ name, target })),
      cache: [...ledger.values()].map((e) => ({
        name: e.name,
        target: e.target,
        cachedAtTick: e.cachedAtTick,
        expiresAtTick: e.expiresAtTick,
        ttlRemaining: e.expiresAtTick - currentTick,
      })),
    };
  }

  return {
    get address() {
      return address;
    },
    evictExpired,
    lookup,
    snapshot,
  };
}

// DOCUMENTS: the Stage 6 component — a cross-subnet Router joining the 10.x
// and 20.x network instances. A frame whose target lives on the other subnet
// takes exactly one router hop (the `routed` counter) and is delivered out
// the matching interface; `isYou` rides through untouched. Nothing lives in
// subnet 20 in Stage 6a besides the router's own presence: an unregistered
// 20.x host fails loud (mirrors network.js), and the router's 20-side
// interface (20.1) is the only reachable target — Stage 6b occupies it with
// the CDN edge.
//
// CHECKS: the constructor rejects a non-mini-IP on either interface and both
// interfaces sitting on the same subnet; an attached frame to a subnet
// neither interface fronts fails loud (no route), and a queued frame whose
// final target is the router's own interface fails loud too (no worker
// lives behind the router in 6a).
export function createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  if (!/^\d+\.\d+$/.test(leftAddress)) {
    throw new Error(`router: invalid mini-IP address ${leftAddress}`);
  }
  if (!/^\d+\.\d+$/.test(rightAddress)) {
    throw new Error(`router: invalid mini-IP address ${rightAddress}`);
  }
  const netOf = (addr) => addr.slice(0, addr.indexOf('.'));
  if (netOf(leftAddress) === netOf(rightAddress)) {
    throw new Error(
      `router: both interfaces must sit on different subnets, got ${leftAddress} and ${rightAddress}`,
    );
  }
  let left = null;
  let right = null;
  let routed = 0;

  // CHECKS: the exit interface is the one whose subnet fronts the target —
  // anything else is an unattached subnet and fails loud.
  function exitFor(to) {
    const net = netOf(to);
    if (net === netOf(rightAddress)) return { network: right, exit: rightAddress };
    if (net === netOf(leftAddress)) return { network: left, exit: leftAddress };
    throw new Error(`router: no route to subnet ${net} (target ${to})`);
  }

  function assertAttached() {
    if (!left || !right) {
      throw new Error('router: no networks attached — call attach({ left, right }) first');
    }
  }

  return {
    get leftAddress() {
      return leftAddress;
    },
    get rightAddress() {
      return rightAddress;
    },

    attach({ left: leftNetwork, right: rightNetwork }) {
      if (!leftNetwork || !rightNetwork) {
        throw new Error('router: attach needs both subnet networks');
      }
      left = leftNetwork;
      right = rightNetwork;
    },

    // Exactly one router hop: the counter increments once per cross-subnet
    // frame, and the frame exits on the interface that fronts its subnet.
    // A frame addressed to the router's own interface terminates at the
    // router (the subnet holds nothing else in 6a) and answers with a slim
    // diagnostic record — no HTTP server lives there.
    forward({ from, to, request, isYou = false }) {
      assertAttached();
      routed += 1;
      const { network, exit } = exitFor(to);
      if (to === exit) {
        return {
          from,
          to,
          request,
          isYou,
          response: `200 Router ${to} (cross-subnet edge)`,
        };
      }
      return { ...network.send({ from, to, request }), isYou };
    },

    // Queue path of the same hop: the frame exits toward its subnet with the
    // original sender address; the router's own interface accepts no queued
    // work (fail-loud over a silent drop).
    forwardQueue({ id, from, to, request, atTick, isYou = false }) {
      assertAttached();
      routed += 1;
      const { network, exit } = exitFor(to);
      if (to === exit) {
        throw new Error(`router: queued work for ${to} has no worker behind the router (stage 6a)`);
      }
      network.deliverToQueue({ id, from, to, request, atTick, isYou });
    },

    snapshot() {
      return { leftAddress, rightAddress, routed };
    },
  };
}

// DOCUMENTS: the network — the wiring that lets two-number mini-IP
// addressable components exchange messages. Today it carries slim HTTP
// requests to a registered server; later stages attach more components
// without changing the send/enqueue contract.
//
// Stage 6: with a `subnet` and a `gateway` attached, a frame whose target
// lives on another subnet is forwarded to the gateway (the cross-subnet
// Router) — exactly one router hop — instead of resolving the target here;
// an unregistered host on the gateway's own subnets still fails loud. With
// no subnet (Stages 1-5) the fabric is unchanged: every unregistered
// address throws.
//
// CHECKS: every address crossing the wire is validated as a two-number
// mini-IP (<net>.<host>), and sends to unregistered hosts fail loud. A
// cross-subnet fabric needs both a subnet and a gateway — either alone is
// rejected at construction.
const MINI_IP = /^\d+\.\d+$/;

export function createNetwork({ subnet = null, gateway = null } = {}) {
  if ((subnet === null) !== (gateway === null)) {
    throw new Error('network: cross-subnet routing needs both a subnet and a gateway');
  }
  const netOf = (addr) => addr.slice(0, addr.indexOf('.'));
  const servers = new Map();

  function validate(addr) {
    if (!MINI_IP.test(addr)) {
      throw new Error(`network: invalid mini-IP address ${addr}`);
    }
  }

  function resolve(address) {
    validate(address);
    const server = servers.get(address);
    if (!server) {
      throw new Error(`network: no server at ${address}`);
    }
    return server;
  }

  function crossSubnet(to) {
    return subnet !== null && netOf(to) !== subnet;
  }

  return {
    registerServer(address, server) {
      validate(address);
      servers.set(address, server);
    },

    resolve,

    send({ from, to, request, isYou = false }) {
      validate(from);
      validate(to);
      if (crossSubnet(to)) {
        return gateway.forward({ from, to, request, isYou });
      }
      const response = resolve(to).handleRequest(request);
      return { from, to, request, response };
    },

    // `isYou` rides through untouched: the engine marks the learner's own
    // interactive-browser request, the server stores it on the queue row.
    deliverToQueue({ id, from, to, request, atTick, isYou = false }) {
      validate(from);
      validate(to);
      if (crossSubnet(to)) {
        gateway.forwardQueue({ id, from, to, request, atTick, isYou });
        return;
      }
      const server = resolve(to);
      server.enqueue({ id, from, to, request, atTick, isYou });
    },
  };
}

// DOCUMENTS: the Stage 6 hosted-DNS trace runner — the hop-by-hop machine
// for a browser path that carries a host (`example.com/about`). trace.js
// delegates only hosted hops here; a host-less path (`/about`) keeps the
// Stage 5 chain byte-identical. Two DNS hops ride in front: Browser -> DNS
// ask, DNS answer with the resolved target, then the browser emits the GET
// with the resolved target and the Stage 5 story follows — 10 hops. An
// unknown name ends the trace after the ask/answer pair: DNS ask + "NX no
// record" answer + the browser rendering the NX card — no GET is emitted
// and the servers never drain.
//
// CHECKS: the hosted/NX/host-less branch keys off the path's first
// character and host syntax — "GET /about" is never hosted (named
// counter-example pinned in test/panel/model-stage6.test.js), and a bare
// name without a path ("example.com") is not a hosted URL either.
export function isHostedPath(path = '') {
  const raw = String(path);
  return raw.length > 0 && !raw.startsWith('/') && raw.includes('/');
}

// Hosted grammar: the URL splits host/path on the first "/" —
// "example.com/about" -> host "example.com", path "/about".
function splitHostPath(raw) {
  const at = raw.indexOf('/');
  return { host: raw.slice(0, at), path: raw.slice(at) };
}

export function createHostedRunner({
  dns,
  lb,
  servers,
  cache = null,
  database = null,
  workerQueue = null,
  bumpTick,
  getTick,
  onServe,
  onFinish,
  serverAddress,
}) {
  // The served response record, held between the drain hop and the serve
  // hop so the learner watches the cache/database lookup before the
  // response leaves the backend (same pattern as the host-less machine).
  let served = null;

  // Serve from the front of the target's queue until the trace's own
  // request (isYou) comes back, or the queue runs dry this tick.
  function drainUntilYou(targetServer) {
    for (;;) {
      const batch = targetServer.step(getTick());
      const you = batch.find((item) => item.isYou);
      if (you || batch.length === 0) return you;
    }
  }

  function backendFor(targetAddress) {
    return servers.find((s) => s.address === targetAddress) ?? servers[0];
  }

  function serve(record, trace) {
    trace.response = record.response;
    trace.status = record.status;
    trace.body = record.body;
    trace.routeId = record.routeId;
    onServe(record);
  }

  // Hop 1: the browser asks DNS 10.60 for the host — the lookup runs now,
  // and the answer hop narrates whatever the resolver actually did.
  function start({ method = 'GET', path = '/about', from = '10.2' }) {
    const { host, path: httpPath } = splitHostPath(String(path));
    const request = `${method} ${path}`;
    const answer = dns.lookup(host, getTick());
    const trace = {
      hop: 1,
      method,
      path,
      from,
      request,
      targetServer: null,
      hosted: true,
      host,
      httpPath,
      dnsStatus: answer.status,
      resolvedTarget: answer.target ?? null,
      nx: answer.status === 'NX',
      cacheStatus: null,
      dbOp: null,
      dbStale: false,
      asyncJob: false,
      response: null,
      status: null,
      body: null,
      routeId: null,
    };
    return { trace, frame: `${from} -> ${dns.address} | ${request} (DNS ask ${host})` };
  }

  // One hop per call (trace.hop values 1..9; hop 10 ends the trace and the
  // machine's hop >= finalHop branch restarts). Returns the hop's frame, or
  // null when nothing moved.
  function step(trace) {
    let frame = null;
    if (trace.hop === 1) {
      trace.hop = 2;
      frame = trace.nx
        ? `${dns.address} -> ${trace.from} | DNS answer ${trace.host} = NX no record`
        : `${dns.address} -> ${trace.from} | DNS answer ${trace.host} = ${trace.resolvedTarget}`;
    } else if (trace.nx) {
      // Final NX hop: the browser renders the NX card — no GET ever leaves
      // the browser, so the servers stay drained.
      trace.hop = 3;
      trace.response = 'NX no record';
      trace.status = 'NX';
      trace.body = 'no record';
      onFinish({
        from: trace.from,
