// DOCUMENTS: Stage 5 worker-queue jobs render one row per pending job with
// its enqueue tick; the queue stats and worker HUD mirror the counters and
// the active job (DESIGN.md queue-jobs-list).
function renderJobsInto(container, jobs) {
  container.replaceChildren(
    ...jobs.map((job) => {
      const item = document.createElement('li');
      item.className = 'route-item';
      item.textContent = `#${job.jobId} · ${job.path} · queued @ tick ${job.queuedAtTick}`;
      return item;
    }),
  );
}

// DOCUMENTS: Stage 6 resolver-cache rows render one row per live ledger
// entry with its remaining TTL in ticks (DESIGN.md #dns-entries-list); an
// empty ledger shows a hint instead of vanishing.
function renderDnsEntries(container, entries) {
  if (entries.length === 0) {
    const hint = document.createElement('span');
    hint.className = 'queue-empty-hint';
    hint.textContent = 'resolver cache empty';
    container.replaceChildren(hint);
    return;
  }
  container.replaceChildren(
    ...entries.map((e) => {
      const item = document.createElement('li');
      item.className = 'route-item';
      item.textContent = `${e.name} = ${e.target} · ttl ${e.ttlRemaining}t`;
      return item;
    }),
  );
}

