  $('node-webserver-2').hidden = !hasLb;
  $('node-cache').hidden = !hasCache;
  $('wire-servers-cache').hidden = !hasCache;
  $('node-db').hidden = !hasDb;
  $('wire-cache-db').hidden = !hasDb;
  $('node-queue').hidden = !hasWorkers;
  $('wire-cache-queue').hidden = !hasWorkers;
  $('node-worker').hidden = !hasWorkers;
  $('wire-queue-worker').hidden = !hasWorkers;
  // Stage 6 cards and the DNS wire column are built in stage6-nodes.js —
  // guard the lookups so early renders cannot crash on a missing node.
  const dnsNode = document.getElementById('node-dns');
  const routerNode = document.getElementById('node-router');
  const dnsWire = document.getElementById('wire-dns');
  if (dnsNode) dnsNode.hidden = !hasStage6;
  if (routerNode) routerNode.hidden = !hasStage6;
  if (dnsWire) dnsWire.hidden = !hasStage6;
  $('network-role-10-1').textContent = hasLb ? 'LoadBalancer -> 10.11, 10.12' : 'WebServer';

