// Which card executes the hop, and which wire lane carries it:
// Stage 1 is emit / route / serve / render; Stage 2 inserts the LB's
// round-robin pick; Stage 3 splits the backend serve into the cache
// lookup (Cache 10.20 answers) and the response emission; Stage 4 adds
// the database hop; Stage 5 adds async worker queue processing. Stage 6
// branches on host syntax: a hosted path walks browser -> DNS ask ->
// DNS answer -> the Stage 5 shape (owner/lane shift +2), a host-less
// path keeps the Stage 5 shape verbatim, and an NX trace ends with the
// browser rendering the resolver's answer.
function stage5Shape(snapshot) {
  const t = snapshot.trace ?? {};
  const backendCard =
    t.targetServer === '10.12' ? 'node-webserver-2' : 'node-webserver';
  const dbLane = t.dbOp === 'WRITE' ? 'packet-req-db' : 'packet-res-db';
  const owners = t.asyncJob
    ? {
        1: 'node-browser',
        2: 'node-network',
        3: 'node-lb',
        4: 'node-queue',
        5: 'node-webserver',
        6: 'node-network',
        7: 'node-browser',
        8: 'node-worker',
      }
    : {
        1: 'node-browser',
        2: 'node-network',
        3: 'node-lb',
        4: 'node-db',
        5: backendCard,
        6: 'node-network',
        7: 'node-browser',
        8: 'node-worker',
      };
  const lanes = t.asyncJob
    ? {
        1: 'packet-req-left',
        2: 'packet-req-right',
        3: 'packet-req-lb',
        4: 'packet-req-queue',
        5: 'packet-res-cache',
        6: 'packet-res-right',
        7: 'packet-res-left',
        8: 'packet-res-db',
      }
    : {
        1: 'packet-req-left',
        2: 'packet-req-right',
        3: 'packet-req-lb',
        4: dbLane,
        5: 'packet-res-cache',
        6: 'packet-res-right',
        7: 'packet-res-left',
        8: 'packet-res-worker',
      };
  return { owners, lanes };
}

