function stepOneHop() {
  const snapshot = engine.traceHop({
    method: els.method.value,
    path: els.urlInput.value,
    from: activeBrowserAddress,
  });
  // Stage 6's per-trace total branches on host syntax (hosted 10 / NX 3 /
  // host-less 8); model.js totalHopsFor is the one source for panel and
  // journey labels alike.
  const totalHops = totalHopsFor(snapshot.stage, snapshot.trace);
  // PINS: hop 1 emission starts a new trace run — that run (whole, hops
  // ascending) floats above the previous run in #journey-log.
  if (snapshot.trace.hop === 1) traceRunId = nextJourneyRun();
  addToJourney(`hop ${snapshot.trace.hop}/${totalHops}`, snapshot.lastFrame, {
    run: traceRunId,
    hop: snapshot.trace.hop,
  });
  updateView(snapshot);
  return snapshot;
}

$('btn-next-hop').addEventListener('click', stepOneHop);

// CHECKS: the play loop and the Go button read the per-trace hop total off
// the snapshot after every hop — a hosted NX trace ends at hop 3/3 (no GET
// is emitted), so a stage-6 total of 10 must stop the loop there instead of
// restarting the trace.
$('btn-play-request').addEventListener('click', () => {
  if (timer) pause();
  const iv = setInterval(() => {
    const snap = stepOneHop();
    if (snap.trace.hop >= totalHopsFor(snap.stage, snap.trace)) clearInterval(iv);
  }, TICK_MS);
});

$('btn-url-go').addEventListener('click', () => {
  if (timer) pause();
  for (let i = 0; i < 24; i += 1) {
    const snap = stepOneHop();
    if (snap.trace.hop >= totalHopsFor(snap.stage, snap.trace)) break;
  }
});

