import { describe, it, expect } from 'vitest';
import { createDns } from '../../js/sim/dns.js';

describe('createDns', () => {
  it('consults the authoritative table only on a miss or an expired entry — a live ledger hit answers with no consult', () => {
    const dns = createDns({ address: '10.60', ttlTicks: 5 });

    // Cold lookup: one authoritative consult, and the ledger fills with the
    // resolved name (cached at tick 0, alive through tick 4).
    expect(dns.lookup('example.com', 0)).toEqual({
      status: 'OK',
      target: '10.1',
      source: 'authoritative',
    });
    let snap = dns.snapshot(0);
    expect(snap.lookups).toBe(1);
    expect(snap.cachedHits).toBe(0);
    expect(snap.cache).toEqual([
      {
        name: 'example.com',
        target: '10.1',
        cachedAtTick: 0,
        expiresAtTick: 5,
        ttlRemaining: 5,
      },
    ]);
    expect(snap.lastLookup).toEqual({
      name: 'example.com',
      status: 'OK',
      source: 'authoritative',
      target: '10.1',
      atTick: 0,
    });

    // CHECKS: a hit inside ttlTicks increments cachedHits with NO
    // authoritative consult — lastLookup records the cache branch.
    expect(dns.lookup('example.com', 4)).toEqual({
      status: 'OK',
      target: '10.1',
      source: 'cache',
    });
    snap = dns.snapshot(4);
    expect(snap.lookups).toBe(2);
    expect(snap.cachedHits).toBe(1);
    expect(snap.lastLookup).toEqual({
      name: 'example.com',
      status: 'OK',
      source: 'cache',
      target: '10.1',
      atTick: 4,
    });

    // CHECKS (named counter-example): an expired entry is NOT answered from
    // the ledger — tick 5 is the first tick the entry is gone, the lookup
    // evicts it and re-consults the authoritative table (cachedHits stays).
    expect(dns.lookup('example.com', 5)).toEqual({
      status: 'OK',
      target: '10.1',
      source: 'authoritative',
    });
    snap = dns.snapshot(5);
    expect(snap.cachedHits).toBe(1);
    expect(snap.evictions).toBe(1);
    expect(snap.cache[0]).toMatchObject({ expiresAtTick: 10, ttlRemaining: 5 });
    expect(snap.lastLookup).toEqual({
      name: 'example.com',
      status: 'OK',
      source: 'authoritative',
      target: '10.1',
      atTick: 5,
    });
  });

  it('an unknown name answers NX with no cache entry and no throw', () => {
    const dns = createDns();
    expect(dns.lookup('nope.example', 0)).toEqual({ status: 'NX' });
    const snap = dns.snapshot(0);
    expect(snap.cache).toEqual([]);
    expect(snap.cachedHits).toBe(0);
    expect(snap.lastLookup).toEqual({
      name: 'nope.example',
      status: 'NX',
      source: 'authoritative',
      target: null,
      atTick: 0,
    });
    // The authoritative table is in-component and Stage 6a carries exactly
    // one name (Stage 6b adds the CDN edge).
    expect(snap.authoritative).toEqual([{ name: 'example.com', target: '10.1' }]);
    expect(snap.address).toBe('10.60');
    expect(snap.ttlTicks).toBe(300);
  });

  it('rejects an invalid mini-IP address and a non-positive or non-integer ttlTicks', () => {
    expect(() => createDns({ address: '1060' })).toThrow(/invalid mini-IP/);
    expect(() => createDns({ ttlTicks: 0 })).toThrow(/ttlTicks/);
    expect(() => createDns({ ttlTicks: 2.5 })).toThrow(/ttlTicks/);
  });
});

import { describe, it, expect } from 'vitest';
import { createRouter } from '../../js/sim/router.js';
import { createNetwork } from '../../js/sim/network.js';
import { createWebServer } from '../../js/sim/webserver.js';

describe('createRouter', () => {
  it('rejects invalid mini-IP interfaces and both interfaces on the same subnet', () => {
    expect(() => createRouter({ leftAddress: '1065' })).toThrow(/invalid mini-IP/);
    expect(() => createRouter({ rightAddress: '201' })).toThrow(/invalid mini-IP/);
    expect(() => createRouter({ leftAddress: '10.65', rightAddress: '10.1' })).toThrow(
      /different subnets/,
    );
  });

  it('same-subnet sends keep the network contract unchanged with the router attached', () => {
    const router = createRouter();
    const left = createNetwork({ subnet: '10', gateway: router });
    const right = createNetwork({ subnet: '20', gateway: router });
    router.attach({ left, right });
    left.registerServer('10.1', createWebServer({ address: '10.1' }));

    // A same-subnet frame resolves on the left network exactly as in
    // Stages 1-5 — the router never sees it.
    expect(left.send({ from: '10.2', to: '10.1', request: 'GET /about' })).toEqual({
      from: '10.2',
      to: '10.1',
      request: 'GET /about',
      response: '200 This is the about page',
    });
    expect(router.snapshot()).toEqual({ leftAddress: '10.65', rightAddress: '20.1', routed: 0 });

    // A subnet neither interface fronts fails loud at the router.
    expect(() => left.send({ from: '10.2', to: '11.1', request: 'GET /' })).toThrow(
      /no route to subnet 11/,
    );
  });

  it('a cross-subnet frame takes exactly one router hop and increments routed', () => {
    const router = createRouter();
    const left = createNetwork({ subnet: '10', gateway: router });
    const right = createNetwork({ subnet: '20', gateway: router });
    router.attach({ left, right });

    // CHECKS: the frame 10.x -> 20.1 rides exactly one router hop — the
    // counter increments once, and the router's 20-side interface is the
    // only reachable target in Stage 6a, so the frame terminates there.
    const record = left.send({ from: '10.2', to: '20.1', request: 'GET /' });
    expect(record).toEqual({
      from: '10.2',
      to: '20.1',
      request: 'GET /',
      isYou: false,
      response: '200 Router 20.1 (cross-subnet edge)',
    });
    expect(router.snapshot()).toEqual({ leftAddress: '10.65', rightAddress: '20.1', routed: 1 });

    // The next cross-subnet frame is its own single hop.
    left.send({ from: '10.2', to: '20.1', request: 'GET /about' });
    expect(router.snapshot().routed).toBe(2);
  });

  it('an unregistered subnet-20 host fails loud (20.9)', () => {
    const router = createRouter();
    const left = createNetwork({ subnet: '10', gateway: router });
    const right = createNetwork({ subnet: '20', gateway: router });
    router.attach({ left, right });
    // CHECKS: subnet 20 holds nothing but the router's own presence in 6a —
    // a send into 20.9 resolves on the right network and throws, mirroring
    // the fail-loud contract of the 10.x fabric.
    expect(() => left.send({ from: '10.2', to: '20.9', request: 'GET /' })).toThrow(
      /no server at 20\.9/,
    );
    // The queued path fails loud the same way.
    expect(() =>
      left.deliverToQueue({ id: '1:1', from: '10.2', to: '20.9', request: 'GET /', atTick: 1 }),
    ).toThrow(/no server at 20\.9/);
  });
});

import { describe, it, expect } from 'vitest';
import { createEngine } from '../../js/sim/engine.js';

describe('stage 6 engine wiring', () => {
  it('instantiates DNS 10.60 and the cross-subnet Router and exposes them on the snapshot', () => {
    const engine = createEngine({ stage: 6 });
    const snap = engine.snapshot();
    expect(snap.dns).toMatchObject({
      address: '10.60',
      ttlTicks: 300,
      lookups: 0,
      cachedHits: 0,
    });
    expect(snap.router).toEqual({ leftAddress: '10.65', rightAddress: '20.1', routed: 0 });
    // The Stage 5 topology is untouched beneath the new components.
    expect(snap.servers.map((s) => s.address)).toEqual(['10.11', '10.12']);
    expect(snap.cache.address).toBe('10.20');
    expect(snap.database.primaryAddress).toBe('10.30');
    expect(snap.workerQueue.address).toBe('10.40');
    // Stages 1-5 expose neither component.
    expect(createEngine({ stage: 5 }).snapshot().dns).toBe(null);
    expect(createEngine({ stage: 5 }).snapshot().router).toBe(null);
    expect(createEngine({ stage: 1 }).snapshot().dns).toBe(null);
  });

  it('a hosted trace asks DNS 10.60, resolves example.com = 10.1, and rides the Stage 5 chain at 10 hops', () => {
    const engine = createEngine({ stage: 6 });
    engine.traceHop({ method: 'GET', path: 'example.com/about' });
    let snap = engine.snapshot();
    expect(snap.trace.hop).toBe(1);
    expect(snap.trace.hosted).toBe(true);
    expect(snap.trace.host).toBe('example.com');
    expect(snap.trace.request).toBe('GET example.com/about');
    expect(snap.dns.lookups).toBe(1);
    expect(snap.lastFrame).toBe('10.2 -> 10.60 | GET example.com/about (DNS ask example.com)');

    engine.traceHop({ method: 'GET', path: 'example.com/about' });
    snap = engine.snapshot();
    expect(snap.trace.resolvedTarget).toBe('10.1');
    expect(snap.dns.cachedHits).toBe(0);
    expect(snap.lastFrame).toBe('10.60 -> 10.2 | DNS answer example.com = 10.1');

    // Hops 3-10: the resolved GET rides the Stage 5 story; the ledger entry
    // lives for ttlTicks (300) and the 200 response lands on the browser.
    for (let hop = 0; hop < 8; hop++) {
      engine.traceHop({ method: 'GET', path: 'example.com/about' });
    }
    snap = engine.snapshot();
    expect(snap.trace.hop).toBe(10);
    expect(snap.trace.request).toBe('GET /about');
    expect(snap.browserDisplay).toMatchObject({ status: 200, body: 'This is the about page' });
    expect(snap.servers.map((s) => s.served)).toEqual([1, 0]);

    // The second hosted trace answers from the ledger: cachedHits +1 with
    // no authoritative consult (lastLookup records the cache branch).
    engine.traceHop({ method: 'GET', path: 'example.com/about' });
    snap = engine.snapshot();
    expect(snap.dns.cachedHits).toBe(1);
    expect(snap.dns.lookups).toBe(2);
    expect(snap.dns.lastLookup).toMatchObject({ source: 'cache', target: '10.1' });
  });

  it('a host-less GET /about keeps the Stage 5 trace shape with no DNS consult', () => {
    const engine = createEngine({ stage: 6 });
    for (let hop = 0; hop < 8; hop++) engine.traceHop({ method: 'GET', path: '/about' });
    const snap = engine.snapshot();
    expect(snap.trace.hop).toBe(8);
    expect(snap.trace.hosted).toBe(false);
    expect(snap.trace.request).toBe('GET /about');
    // Plain paths never touch DNS: zero lookups, an empty ledger.
    expect(snap.dns.lookups).toBe(0);
    expect(snap.dns.cache).toEqual([]);
    expect(snap.browserDisplay).toMatchObject({ status: 200, body: 'This is the about page' });
  });

  it('nope.example/about renders NX without emitting a GET', () => {
    const engine = createEngine({ stage: 6 });
    engine.traceHop({ method: 'GET', path: 'nope.example/about' });
    expect(engine.snapshot().trace.hop).toBe(1);
    engine.traceHop({ method: 'GET', path: 'nope.example/about' });
    let snap = engine.snapshot();
    expect(snap.trace.nx).toBe(true);
    expect(snap.lastFrame).toBe('10.60 -> 10.2 | DNS answer nope.example = NX no record');
    // No GET has left the browser: the servers stay drained.
    expect(snap.servers.every((s) => s.served === 0)).toBe(true);

    engine.traceHop({ method: 'GET', path: 'nope.example/about' });
    snap = engine.snapshot();
    expect(snap.trace.hop).toBe(3);
    expect(snap.browserDisplay).toMatchObject({ status: 'NX', body: 'no record' });
    expect(snap.servers.every((s) => s.served === 0)).toBe(true);
    expect(snap.dns.lookups).toBe(1);
    expect(snap.dns.cache).toEqual([]);
  });
});

