/* World-space backdrop: concentric rings, spokes, satellites. The SVG's box
   is shifted so its viewBox origin lines up with world (0,0). Covers full
   circles up to r = 3000, so Stage 3's five rings at the max ring gap
   (r5 = 5 * 560 = 2800) do not clip. */
.orrery-svg {
  position: absolute;
  left: -3000px;
  top: -3000px;
  width: 6000px;
  height: 6000px;
  pointer-events: none;
}

.orrery-ring {
  fill: none;
  stroke: var(--border);
  stroke-width: 1.5;
}

.orrery-core {
  fill: var(--accent-soft);
  stroke: var(--accent);
